(()=>{'use strict';const daily=document.querySelector('[data-play-daily]');if(!daily)return;fetch('js/play-catalogue.json').then(r=>{if(!r.ok)throw Error('catalogue');return r.json();}).then(games=>{const d=new Date(),day=Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/86400000,game=games[day%games.length];daily.querySelector('h2').textContent=game.title;daily.querySelector('p').textContent=game.description;daily.querySelector('a').href=game.route+'?seed='+day;daily.querySelector('a').textContent='Play today';}).catch(()=>{});document.querySelectorAll('.play-directory-nav a').forEach(a=>a.addEventListener('click',()=>{const section=document.getElementById(a.hash.slice(1));if(section)section.open=true;}));if(location.hash){const section=document.getElementById(location.hash.slice(1));if(section)section.open=true;}})();
